--- cat animator hash define
local StringToHash           = Animator.StringToHash
local IdleHash               = StringToHash("idle")
local CatActionSleepAniHash  = {
    [StringToHash("sleep01_01")] = true,
    [StringToHash("sleep01_02")] = true,
    [StringToHash("sleep01_03")] = true,
}
local CatActionStage1AniHash = {
    [StringToHash("cattouch_01_01_02")] = true,
    [StringToHash("cattouch_01_02_02")] = true,
    [StringToHash("cattouch_01_03_02")] = true,
}
