---@class CatTouchController
local CatTouchController = Class('CatTouchController')

function CatTouchController:__init()
    self._isCanTouch = nil
    self._animator = nil
end

function CatTouchController:__delete()
    self.IsDestroy = true
    self:Release()
end


--region lounge init

function CatTouchController:Init(cardSkin, parent, idleFlag)
    cardSkin = checkNumber(cardSkin)
    if self._cardSkin == cardSkin then return end
    if self._cardSkin then
        self:Release()
    end
    if cardSkin <= 0 then
        return
    end
    
    self._cardSkin         = cardSkin
    ---@type CardSkinVo
    local cardSkinVo       = cardConfMgr:GetCardSkinBySkinId(cardSkin)
    
    local catPath          = self:GetCatPath(cardSkinVo)
    self._catLoader        = ResourceModule.LoadBundleAsync(catPath)

    self._isCanTouch       = true
    if not self:IsMonsterCard(cardSkinVo) then
        self:InitCatControllerLoader(cardSkinVo)
    end
    
    return self:Instance(parent, idleFlag)
end

function CatTouchController:Instance(parent, idleFlag)
    self._parent = parent
    self._instanceCo = CoStart(function()
        xTry(function()
            local catGo      = CardProgressionUtils.CustomInstantiate(self._catLoader, parent)
            self:InitCatController(catGo)
            self:UpdateTouchState(true, true)
            self._catGo = catGo
            self:HandlerPlayCatAni(CardProgressionConstants.CatTouchFlag.Default, idleFlag or CardProgressionConstants.CatTouchIdleFlag.Default)

            self._instanceCo = nil
        end)
    end)
    return self._instanceCo
end

function CatTouchController:CheckIsLoadComplete()
    return isNull(self._instanceCo)
end

--endregion

--region home init


function CatTouchController:InitCatTouchController(cardSkin, catGo, isCanTouch, isForce)
    ---@type CardSkinVo
    local cardSkinVo       = cardConfMgr:GetCardSkinBySkinId(cardSkin)
    if self:IsMonsterCard(cardSkinVo) then
        return
    end

    local touchFlag = CardProgressionConstants.CatTouchFlag.IdleQuit
    local idleFlag  = CardProgressionConstants.CatTouchIdleFlag.Default
    ---_animator 为空表示在非主界面切换过猫
    if self._cardSkin == cardSkin and isNotNull(self._animator) then
        self:UpdateTouchState(isCanTouch, isForce, touchFlag, idleFlag)
        return 
    end

    self._cardSkin = cardSkin
    if not self:InitCatControllerLoader(cardSkinVo) then
        return
    end
    if not isNull(self._instanceCo) then
        CoStop(self._instanceCo)
        self._instanceCo = nil
    end
    self._instanceCo = CoStart(function()
        self:InitCatControllerLoader(cardSkinVo)
        self:InitCatController(catGo)
        self:UpdateTouchState(isCanTouch, isForce, touchFlag, idleFlag)
        
    end)
end


--endregion

--region common init

function CatTouchController:IsMonsterCard(cardSkinVo)
    return CardUtils.IsMonsterCard(cardSkinVo.roleId)
end

function CatTouchController:InitCatControllerLoader(cardSkinVo)
    local controllerPath   = self:GetAnimatorPath(cardSkinVo)
    if self._controllerPath == controllerPath and isNotNull(self._controllerLoader) then return false end
    self._controllerPath   = controllerPath
    self._controllerLoader = ResourceModule.LoadBundleAsync(controllerPath)
    return true
end

function CatTouchController:InitCatController(catGo)
    local controllerLoader = self._controllerLoader
    if isNull(controllerLoader) then return end
    if isNull(catGo) then return end
    ---@type UnityEngine.Animator
    local animator         = KTool.GetOrAddComponent(catGo, CardProgressionConstants.CompType.AnimatorType)
    self._animator         = animator
    self._originController = animator.runtimeAnimatorController

    local controller       = CardProgressionUtils.CustomInstantiate(controllerLoader, nil, catGo)
    self._controllerLoader = nil
    self._touchController  = controller

    self._weapons = {}
    local meshFilters = catGo:GetComponentsInChildren(typeof(CS.UnityEngine.MeshFilter))
    for i = 0, meshFilters.Length - 1, 1 do
        local meshFilter = meshFilters[i]
        if string.find(meshFilter.sharedMesh.name, "weapon") then
            table.insert(self._weapons, meshFilter.gameObject)
        end
    end
    
end

function CatTouchController:UpdateTouchState(isCanTouch, isForce, touchFlag, idleFlag)
    if self._isCanTouch ~= isCanTouch or isForce then
        self._isCanTouch = isCanTouch
        if isNull(self._animator) then return end

        if not isCanTouch and not isNull(self._originController) then
            self._animator.runtimeAnimatorController = self._originController
        end
        if isCanTouch and not isNull(self._touchController) then
            self._animator.runtimeAnimatorController = self._touchController
            if touchFlag and idleFlag then
                self:HandlerPlayCatAni(touchFlag, idleFlag)
            end
        end

        if self._weapons then
            for i, weapon in ipairs(self._weapons) do
                if isNotNull(weapon) then
                    KTool.SetActive(weapon, not isCanTouch)
                end
            end
            
        end
    end

end

--endregion


--region logic

function CatTouchController:RandomAction()
    if not self._isCanTouch then return false end
    local CatTouchActionFlag = CardProgressionConstants.CatTouchActionFlag
    local actionId = CatTouchActionFlag[math.random(1, #CatTouchActionFlag)]
    return self:HandlerPlayCatAni(actionId, CardProgressionConstants.CatTouchIdleFlag.Default)
end

function CatTouchController:PlayActionByIndex(index)
    local CatTouchActionFlag = CardProgressionConstants.CatTouchActionFlag
    local actionId           = CatTouchActionFlag[index]
    return self:HandlerPlayCatAni(actionId, CardProgressionConstants.CatTouchIdleFlag.Default)
end

---EnterDeepInteraction
---进入深度交互
function CatTouchController:EnterDeepInteraction()
    if self:IsInteractionLoop() then
        return self:HandlerPlayCatAni(CardProgressionConstants.CatTouchFlag.EnterDeepInteraction, CardProgressionConstants.CatTouchIdleFlag.Default)
    end
    return false

end

---QuitDeepInteraction
---退出深度交互
function CatTouchController:QuitDeepInteraction()
    local shortNameHash = self:GetAnimatorStateInfoShortHash()
    if CatActionStage2AniHash[shortNameHash] then
        self:HandlerPlayCatAni(CardProgressionConstants.CatTouchFlag.QuitDeepInteraction, CardProgressionConstants.CatTouchIdleFlag.Default)
    end
    
end

function CatTouchController:EnterIdle()
    self:HandlerPlayCatAni(CardProgressionConstants.CatTouchFlag.IdleQuit, CardProgressionConstants.CatTouchIdleFlag.Default)
end

function CatTouchController:EnterStanding()
    self:HandlerPlayCatAni(CardProgressionConstants.CatTouchFlag.Default, CardProgressionConstants.CatTouchIdleFlag.Default)
end

function CatTouchController:EnterSit()
    self:HandlerPlayCatAni(CardProgressionConstants.CatTouchFlag.Default, CardProgressionConstants.CatTouchIdleFlag.Sit)
end

function CatTouchController:EnterSleep()
    self:HandlerPlayCatAni(CardProgressionConstants.CatTouchFlag.Default, CardProgressionConstants.CatTouchIdleFlag.Sleep)
end

