    local face = transform:Find(path)
    local targetNode
    if isNotNull(face) then
        -- ---@type UnityEngine.SkinnedMeshRenderer
        -- local render = face.gameObject:GetComponent(typeof(CS.UnityEngine.SkinnedMeshRenderer))
