function CatTouchController:UpdateCatShowState(isShow)
    if isNull(self._catGo) then return end
    KTool.SetActive(self._catGo, isShow)
end

---HandlerPlayCatAni
---处理播放猫动画
---@param touchFlag number 
---@param idleFlag number 
---@return boolean 是否触发动画播放成功
function CatTouchController:HandlerPlayCatAni(touchFlag, idleFlag)
    if not self._isCanTouch then return false end
    ---@type UnityEngine.Animator
    local animator = self._animator
    if isNull(animator) then return  false end
    animator:SetInteger(CardProgressionConstants.AnimatorHash.IdleHash,  idleFlag)
    animator:SetInteger(CardProgressionConstants.AnimatorHash.TouchHash, touchFlag)
    return true
end


function CatTouchController:Release()
    self._cardSkin = nil
    if not isNull(self._instanceCo) then
        CoStop(self._instanceCo)
        self._instanceCo = nil
    end
    if not isNull(self._catGo) then
        KTool.SafeDelete(self._catGo.gameObject)
        self._catGo = nil
    end
    self._controllerPath = nil
    ---理论上 oldController 是跟着猫创建的 属于猫依赖的loader  如果猫的 loader卸载了 它也会跟着卸载 所以这里直接置空
    self._originController = nil
    
    self._animator = nil
end
--endregion


--region get/set

---GetAnimatorPath
---@param cardSkinVo CardSkinVo
function CatTouchController:GetAnimatorPath(cardSkinVo)
    local cardId         = cardSkinVo.roleId
    ---@type CardVo
    local cardVo         = cardConfMgr:GetCardByRefId(cardId)
    local characterId    = cardVo.characterId
    local controllerPath = string.format(CardProgressionConstants.PrefabPath.CatTouchControllerPath, characterId)
    return controllerPath
end

---GetCatPath
---@param cardSkinVo CardSkinVo
function CatTouchController:GetCatPath(cardSkinVo)
    local catPrefab  = string.format(CardProgressionConstants.PrefabPath.CatLobbyPath, cardSkinVo.catPrefab)
    return catPrefab
end

function CatTouchController:GetIsCanTouch()
    return self._isCanTouch
end

---GetAnimatorStateInfo
---@return UnityEngine.AnimatorStateInfo
function CatTouchController:GetAnimatorStateInfoShortHash()
    if not self._isCanTouch then return  end
    ---@type UnityEngine.Animator
    local animator = self._animator
    if isNull(animator) then return  end
    ---@type UnityEngine.AnimatorStateInfo
    local info = animator:GetCurrentAnimatorStateInfo(0)
    return info.shortNameHash
end

function CatTouchController:IsIdle()
    local shortNameHash = self:GetAnimatorStateInfoShortHash()
    return shortNameHash == IdleHash
end

function CatTouchController:IsSleep()
    local shortNameHash = self:GetAnimatorStateInfoShortHash()
    return CatActionSleepAniHash[shortNameHash] == true
end

function CatTouchController:IsInteractionLoop()
    local shortNameHash = self:GetAnimatorStateInfoShortHash()
    return CatActionStage1AniHash[shortNameHash] == true
end

function CatTouchController:GetCatTrans()
    ---@type UnityEngine.Animator
    local animator = self._animator
    if isNull(animator) then return  end
    return animator.transform
end

